    # If there's a delimiter like '||' or '|' or 'User:' after, cut it off
    s = re.split(r'\s*\|\||\s*\||\s+User:|\s+Instance:|\s+Recall:', s)[0].strip()
    # ISO-like YYYY-MM-DD at start
    if len(s) >= 10 and s[4] == '-':
        try:
            return datetime.datetime.strptime(s[:10], "%Y-%m-%d")
        except:
            pass
    # Try a set of common formats
    for fmt in ("%b %d, %Y", "%m/%d/%Y", "%d/%m/%Y", "%B %d, %Y"):
        try:
            return datetime.datetime.strptime(s, fmt)
        except:
            pass
    # Try to extract numbers like "Jan 26, 2023" with extra spaces
    m = re.search(r'([A-Za-z]+)\s+(\d{1,2}),\s*(\d{4})', s)
    if m:
        try:
            return datetime.datetime.strptime(m.group(0), "%b %d, %Y")
        except:
            try:
                return datetime.datetime.strptime(m.group(0), "%B %d, %Y")
            except:
                pass
    # Try numeric with dashes
    m2 = re.search(r'(\d{1,2})[-/](\d{1,2})[-/](\d{4})', s)
    if m2:
        a,b,c = m2.groups()
        # ambiguous day/month — assume MM/DD/YYYY if first<=12 else DD/MM/YYYY
        try:
            if int(a) <= 12:
                return datetime.datetime.strptime(f"{a}/{b}/{c}", "%m/%d/%Y")
            else:
                return datetime.datetime.strptime(f"{a}/{b}/{c}", "%d/%m/%Y")
        except:
            pass
    return None

