def compose_changes(a_ops, b_ops):
    """
    Compose two change sets a_ops and b_ops into a single change set that has the same
    effect as applying a_ops then b_ops.

    Op representation (lists of tuples):
      ('retain', n)       - keep next n characters from the document
      ('insert', text)    - insert text at current position
      ('delete', n)       - delete next n characters from the document
    """

    def iter_ops(ops):
        for op in ops:
            typ = op[0]
            if typ == 'retain' or typ == 'delete':
                yield (typ, int(op[1]))
            elif typ == 'insert':
                yield (typ, str(op[1]))
            else:
                raise ValueError(f'Unknown op type: {typ}')

    a_iter = iter(iter_ops(a_ops))
    b_iter = iter(iter_ops(b_ops))

    a_head = None
    b_head = None

    def fetch_a():
        nonlocal a_head
        try:
            a_head = next(a_iter)
        except StopIteration:
            a_head = None

    def fetch_b():
        nonlocal b_head
        try:
            b_head = next(b_iter)
        except StopIteration:
            b_head = None

    fetch_a()
    fetch_b()

    result = []

    def push(op):
        if not result:
            result.append(op)
            return
        last = result[-1]
        if last[0] == op[0]:
            if op[0] == 'insert':
                result[-1] = ('insert', last[1] + op[1])
            else:
                result[-1] = (op[0], last[1] + op[1])
        else:
            result.append(op)

    def consume_a(n):
        nonlocal a_head
        if a_head is None:
            return None
        typ, val = a_head
        if typ == 'insert':
            l = len(val)
            if n >= l:
                consumed = ('insert', val)
                fetch_a()
                return consumed
            else:
                consumed_str = val[:n]
                remaining_str = val[n:]
                a_head = ('insert', remaining_str)
                return ('insert', consumed_str)
        else:
            if n >= val:
                consumed = (typ, val)
                fetch_a()
                return consumed
            else:
                a_head = (typ, val - n)
                return (typ, n)

    def consume_b(n):
        nonlocal b_head
        if b_head is None:
            return None
        typ, val = b_head
        if typ == 'insert':
            l = len(val)
            if n >= l:
                consumed = ('insert', val)
                fetch_b()
                return consumed
            else:
                consumed_str = val[:n]
                remaining = val[n:]
                b_head = ('insert', remaining)
                return ('insert', consumed_str)
        else:
            if n >= val:
                consumed = (typ, val)
                fetch_b()
                return consumed
            else:
                b_head = (typ, val - n)
                return (typ, n)

    while b_head is not None:
        b_typ, b_val = b_head

        if b_typ == 'insert':
            push(('insert', b_val))
            fetch_b()
            continue

        if b_typ == 'retain':
            remaining = b_val
            while remaining > 0:
                if a_head is None:
                    push(('retain', remaining))
                    remaining = 0
                    fetch_b()
                    break

                a_typ, a_val = a_head
                if a_typ == 'insert':
                    insert_str = a_val
                    l = len(insert_str)
                    take = min(remaining, l)
                    push(('insert', insert_str[:take]))
                    consume_a(take)
                    remaining -= take
                elif a_typ == 'retain':
                    take = min(remaining, a_val)
                    push(('retain', take))
                    consume_a(take)
                    remaining -= take
                elif a_typ == 'delete':
                    consume_a(a_val)
                else:
                    raise ValueError("Unexpected a_typ")
            continue

        if b_typ == 'delete':
            remaining = b_val
            while remaining > 0:
                if a_head is None:
                    push(('delete', remaining))
                    remaining = 0
                    fetch_b()
                    break

                a_typ, a_val = a_head
                if a_typ == 'insert':
                    l = len(a_val)
                    take = min(remaining, l)
                    consume_a(take)
                    remaining -= take
                elif a_typ == 'retain':
                    take = min(remaining, a_val)
                    push(('delete', take))
                    consume_a(take)
                    remaining -= take
                elif a_typ == 'delete':
                    consume_a(a_val)
                else:
                    raise ValueError("Unexpected a_typ")
            fetch_b()
            continue

        fetch_b()

    while a_head is not None:
        a_typ, a_val = a_head
        if a_typ == 'insert':
            push(('insert', a_val))
            fetch_a()
        elif a_typ == 'retain':
            push(('retain', a_val))
            fetch_a()
        elif a_typ == 'delete':
            push(('delete', a_val))
            fetch_a()
        else:
            fetch_a()

    cleaned = []
    for op in result:
        if op[0] == 'insert' and op[1] == '':
            continue
        if (op[0] == 'retain' or op[0] == 'delete') and op[1] == 0:
            continue
        cleaned.append(op)

    return cleaned

