    # Now find names that satisfy all categories
    required = set(kws.keys())
    matches = [n for n,cats in name_cats.items() if required.issubset(cats)]
    # If none found, try a relaxed match: allow coedited condition to be inferred by presence of same surname co-editor in 2010
    if not matches:
        # search for "co-edited" or "co-edited ... 2010" snippets and look for pairs with same surname
