                    ni = names[i]; nj = names[j]
                    if ni.split()[-1] == nj.split()[-1]:
                        # assign coedited_2010_same_surname to both if other categories match
                        for n in [ni, nj]:
                            # assign other cats if found nearby by searching within document for e.g., "PhD 1989" near name
                            if any(r for r,b,a in search(input_0, n)[:10]):
