    body = ""
    for sheet_name, rows in sheets:
        safe_name = sheet_name.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
        body += f'<Worksheet ss:Name="{safe_name}">\n<Table>\n'
        for r,row in enumerate(rows):
            body += "<Row>\n"
            for cell in row:
                text = cell.get("text","")
                color = cell.get("color", None)
                style_id = ""
                if r == 0:
