                body += f'<Cell{style_id}><Data ss:Type="String">{safe_text}</Data></Cell>\n'
            body += "</Row>\n"
        body += "</Table>\n</Worksheet>\n"
    footer = "</Workbook>"
    return header + styles + body + footer

