# Compute effective multipliers and discounts for the given series/rates

# Series A: 30-10-2.5%
mult_a = (1 - 0.30) * (1 - 0.10) * (1 - 0.025)
eff_disc_a = 1 - mult_a

# Series B: 25-15-2%
mult_b = (1 - 0.25) * (1 - 0.15) * (1 - 0.02)
eff_disc_b = 1 - mult_b

# Series C: 15-15%
mult_c = (1 - 0.15) * (1 - 0.15)
eff_disc_c = 1 - mult_c

# Single rate: 30%
mult_s30 = (1 - 0.30)
eff_disc_s30 = 1 - mult_s30

mult_a, eff_disc_a, mult_b, eff_disc_b, mult_c, eff_disc_c, mult_s30, eff_disc_s30

