class Solution:
    def isValid(self, word: str) -> bool:
        """
        Return True if `word` is valid according to the rules:
        - length at least 3
        - contains only digits and English letters (upper/lower)
        - contains at least one vowel (a, e, i, o, u, case-insensitive)
        - contains at least one consonant (English letter that's not a vowel)
        """
        if len(word) < 3:
            return False

        vowels = set("aeiouAEIOU")
        has_vowel = False
        has_consonant = False

        for ch in word:
            # allowed characters: digits or English letters
            if ch.isdigit():
                continue
            if ch.isalpha():
                if ch in vowels:
                    has_vowel = True
                else:
                    has_consonant = True
            else:
                # any other character (like '@', '#', '$') is invalid
                return False

        return has_vowel and has_consonant
