from typing import List

class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        """
        Return the K-or of nums: for each bit i, set bit i in the result
        iff at least k elements of nums have bit i set.
        """
        result = 0
        # nums[i] < 2^31, so check bits 0..30
        for bit in range(31):
            mask = 1 << bit
            count = 0
            for x in nums:
                if x & mask:
                    count += 1
                    # early exit if we've reached k
                    if count >= k:
                        result |= mask
                        break
        return result

class Solution:
    def findKOr(self, nums: list[int], k: int) -> int:
        # Count how many numbers have each bit set
        # nums[i] < 2^31 so bits 0..30 inclusive may appear
        bit_counts = [0] * 31
        for x in nums:
            for b in range(31):
                if x >> b & 1:
                    bit_counts[b] += 1
        res = 0
        for b in range(31):
            if bit_counts[b] >= k:
                res |= (1 << b)
        return res

