class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        n = len(s)
        # Precompute binary representations of powers of 5 up to length n
        pow5 = set()
        val = 1
        while True:
            b = bin(val)[2:]
            if len(b) > n:
                break
            pow5.add(b)
            val *= 5

        INF = 10**9
        dp = [INF] * (n + 1)
        dp[n] = 0  # zero substrings needed for empty suffix

        # dp[i] = min number of beautiful substrings for s[i:]
        for i in range(n - 1, -1, -1):
            if s[i] == '0':
                # can't start a beautiful substring with '0'
                continue
            # try all end positions j for substring s[i:j]
            for j in range(i + 1, n + 1):
                sub = s[i:j]
                if sub in pow5 and dp[j] != INF:
                    dp[i] = min(dp[i], 1 + dp[j])

        return dp[0] if dp[0] != INF else -1

