from typing import List
import math

class DSU:
    def __init__(self, n: int):
        self.parent = list(range(n))
        self.size = [1] * n

    def find(self, x: int) -> int:
        while self.parent[x] != x:
            self.parent[x] = self.parent[self.parent[x]]
            x = self.parent[x]
        return x

    def union(self, a: int, b: int) -> bool:
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        return True

class Solution:
    def canTraverseAllPairs(self, nums: List[int]) -> bool:
        n = len(nums)
        if n <= 1:
            return True
        # If any value is 1 and n > 1, it cannot connect to any other (gcd(1,x)=1)
        if any(x == 1 for x in nums):
            return False

        maxv = max(nums)
        # build smallest prime factor (spf) sieve
        spf = list(range(maxv + 1))
        if maxv >= 0:
            spf[0] = 0
        if maxv >= 1:
            spf[1] = 1
        limit = int(math.isqrt(maxv))
        for i in range(2, limit + 1):
            if spf[i] == i:
                step = i
                start = i * i
                for j in range(start, maxv + 1, step):
                    if spf[j] == j:
                        spf[j] = i

        def factorize_unique(x: int):
            primes = set()
            while x > 1:
                p = spf[x]
                primes.add(p)
                while x % p == 0:
                    x //= p
            return primes

        dsu = DSU(n)
        prime_to_index = {}

        for i, val in enumerate(nums):
            primes = factorize_unique(val)
            for p in primes:
                if p in prime_to_index:
                    dsu.union(i, prime_to_index[p])
                else:
                    prime_to_index[p] = i

        root0 = dsu.find(0)
        for i in range(1, n):
            if dsu.find(i) != root0:
                return False
        return True
