import sys

MOD = 10**9 + 7

class Solution:
    def numberOfWays(self, n: int, x: int) -> int:
        # generate powers i^x such that i^x <= n
        powers = []
        i = 1
        while True:
            p = i ** x
            if p > n:
                break
            powers.append(p)
            i += 1

        # subset-sum count with each power used at most once (0/1 knapsack counting)
        dp = [0] * (n + 1)
        dp[0] = 1
        for p in powers:
            for s in range(n, p - 1, -1):
                dp[s] = (dp[s] + dp[s - p]) % MOD
        return dp[n]

