def max_sum_squares(nums, k):
    n = len(nums)
    # count bits up to 31 (since nums[i] <= 1e9)
    BIT = 31
    cnt = [0] * BIT
    for x in nums:
        for b in range(BIT):
            if x >> b & 1:
                cnt[b] += 1
    vals = [0] * n
    # For each bit, assign that bit to as many earliest vals as count
    for b in range(BIT):
        bitval = 1 << b
        c = cnt[b]
        for i in range(c):
            vals[i] += bitval
    vals.sort(reverse=True)
    res = 0
    for i in range(min(k, n)):
        res = (res + (vals[i] * vals[i]) % MOD) % MOD
    return res

