def nth_repunit_trio(N):
    # Find minimal L such that repunits up to length L produce at least N distinct triple-sums.
    # We'll grow L exponentially until we have enough, with an upper cap.
    cap = 500  # safe upper bound for lengths; well within performance limits for N <= 333
    L = 1
    while True:
        if L > cap:
            L = cap
        reps = []
        r = 0
        for _ in range(L):
            r = r * 10 + 1
            reps.append(r)
        # pair sums for unordered pairs (i <= j)
        pair_sums = set()
        for i in range(L):
            ri = reps[i]
            for j in range(i, L):
                pair_sums.add(ri + reps[j])
        # triple sums: add every rep to each pair-sum (this covers unordered triples)
        triple_sums = set()
        for s in pair_sums:
            for ri in reps:
                triple_sums.add(s + ri)
        if len(triple_sums) >= N or L == cap:
            # sort and return N-th smallest (1-indexed)
            sorted_triples = sorted(triple_sums)
            return sorted_triples[N-1]
        L *= 2

