class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        n = len(s)
        la = len(a)
        lb = len(b)
        a_pos = []
        b_pos = []
        # collect start indices where a and b occur
        for i in range(0, n - la + 1):
            if s[i:i+la] == a:
                a_pos.append(i)
        for j in range(0, n - lb + 1):
            if s[j:j+lb] == b:
                b_pos.append(j)
        res = []
        if not b_pos:
            return res
        # b_pos is already in increasing order; use binary search for nearest
        for i in a_pos:
            # find insertion point
            idx = bisect.bisect_left(b_pos, i)
            ok = False
            if idx < len(b_pos):
                if abs(b_pos[idx] - i) <= k:
                    ok = True
            if idx > 0 and not ok:
                if abs(b_pos[idx-1] - i) <= k:
                    ok = True
            if ok:
                res.append(i)
        return res

