class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition_to_target(num: int, target: int) -> bool:
            s = str(num)
            L = len(s)
            @lru_cache(None)
            def dfs(pos: int, cur_sum: int) -> bool:
                if cur_sum > target:
                    return False
                if pos == L:
                    return cur_sum == target
