#!/usr/bin/env python3
import sys

MOD = 10**9 + 7

def modinv(x):
    return pow(x, MOD-2, MOD)

def prepare_fact(n):
    fact = [1] * (n+1)
    invfact = [1] * (n+1)
    for i in range(1, n+1):
        fact[i] = fact[i-1] * i % MOD
    invfact[n] = modinv(fact[n])
    for i in range(n, 0, -1):
        invfact[i-1] = invfact[i] * i % MOD
    return fact, invfact

def choose(n, k, fact, invfact):
    if k < 0 or n < 0 or n < k:
        return 0
    return fact[n] * invfact[k] % MOD * invfact[n-k] % MOD

def compositions_bounded(S, m, limit, fact, invfact):
    # number of ways to write S as sum of m integers each in [1, limit]
    if m == 0:
        return 1 if S == 0 else 0
    if S < m or S > m * limit:
        return 0
    T = S - m  # transform to nonnegative variables y_i in [0, limit-1], sum T
    U = limit - 1
    # inclusion-exclusion: sum_{j=0}^{floor(T/(U+1))} (-1)^j C(m, j) * C(T - j*(U+1) + m -1, m-1)
    res = 0
    maxj = T // (U+1)
    for j in range(0, maxj+1):
        sign = -1 if (j % 2 == 1) else 1
        ways_choose_j = choose(m, j, fact, invfact)
        remaining = T - j * (U+1)
        # number of nonnegative solutions of m variables summing to 'remaining' is C(remaining + m -1, m-1)
        ways_split = choose(remaining + m - 1, m - 1, fact, invfact)
        term = ways_choose_j * ways_split % MOD
        if sign == 1:
            res = (res + term) % MOD
        else:
            res = (res - term) % MOD
    return res

def numberOfStableArrays(zero, one, limit):
    # Precompute factorials up to a safe bound
    # The largest n we might need in choose is roughly (max(S) - j*limit + m -1) where S<=max(zero,one)
    # Safe upper bound: zero + one + 5
    N = zero + one + 5
    fact, invfact = prepare_fact(N)
    ans = 0
    total_len = zero + one
    # iterate starting bit: 0 or 1
    for start in (0, 1):
        # number of blocks k ranges from 1 to total_len
        for k in range(1, total_len + 1):
            if start == 0:
                b0 = (k + 1) // 2
                b1 = k // 2
            else:
                b1 = (k + 1) // 2
                b0 = k // 2
            # each block must have at least 1 element and at most limit
            if b0 > zero or b1 > one:
                continue
            # compute ways to partition zeros into b0 blocks and ones into b1 blocks
            ways0 = compositions_bounded(zero, b0, limit, fact, invfact)
            if ways0 == 0:
                continue
            ways1 = compositions_bounded(one, b1, limit, fact, invfact)
            if ways1 == 0:
                continue
            ans = (ans + ways0 * ways1) % MOD
    return ans

def main():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    nums = list(map(int, data))
    # Support either three numbers or three lines with each number
    zero, one, limit = nums[0], nums[1], nums[2]
    print(numberOfStableArrays(zero, one, limit))

if __name__ == "__main__":
    main()

