        (0,4,8),(2,4,6)           # diags
    ]

    from functools import lru_cache

    @lru_cache(maxsize=None)
    def dfs(board):
        # board: tuple of 9 ints
        # check immediate line winner
        for (x,y,z) in lines:
            v = board[x]
            if v != 0 and board[y] == v and board[z] == v:
                return True if v == 1 else False
        # count whites
        k = sum(1 for v in board if v != 0)
        if k == 9:
            # game ends, compare scores
            s = 0
            for i, v in enumerate(board):
                if v == 1:
                    s += A[i]
                elif v == 2:
                    s -= A[i]
            return True if s > 0 else False

        turn_takahashi = (k % 2 == 0)
        # For each available move, simulate
        if turn_takahashi:
            # Takahashi tries to find any move leading to his win
            for i in range(9):
                if board[i] == 0:
                    nb = list(board)
                    nb[i] = 1
                    if dfs(tuple(nb)):
                        return True
            return False
        else:
            # Aoki's turn: he tries to force Aoki win
            for i in range(9):
                if board[i] == 0:
                    nb = list(board)
                    nb[i] = 2
                    if not dfs(tuple(nb)):
                        return False
            return True

    start = tuple([0]*9)
    tak_wins = dfs(start)
    print("Takahashi" if tak_wins else "Aoki")

