class Solution:
    def minimumCost(self, s: str) -> int:
        def min_cost_to_target(s: str, t: str) -> int:
            n = len(s)
            r = [1 if c != t else 0 for c in s]
            INF = 10**30
            dp_cur = [INF, INF]
            dp_cur[0] = 0
            for i in range(n):
                dp_next = [INF, INF]
                for S in (0,1):
                    if dp_cur[S] >= INF:
                        continue
                    base = dp_cur[S]
                    for u in (0,1):
                        newS = (S + u) & 1
                        cost_add = u * (i + 1)
                        if i <= n - 2:
                            v = (u + r[i] + r[i+1]) & 1
                            cost_add += v * (n - (i+1))
                        cand = base + cost_add
                        if cand < dp_next[newS]:
                            dp_next[newS] = cand
                dp_cur = dp_next
            ans = INF
            for S in (0,1):
                v0 = (r[0] + S) & 1
                total = dp_cur[S] + v0 * n
                if total < ans:
                    ans = total
            return ans

        return min(min_cost_to_target(s, '0'), min_cost_to_target(s, '1'))
